-- Partial relation/function inventory only; not complete catalog parity.
BEGIN TRANSACTION READ ONLY; WITH objects AS (SELECT 'relation:'||n.nspname||'.'||c.relname AS identity, md5(jsonb_build_array(c.relkind,c.relrowsecurity,c.relforcerowsecurity,c.reloptions,pg_get_userbyid(c.relowner),c.relacl)::text) AS fingerprint FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','private','credentialing') AND c.relkind IN ('r','p','v','m','S','f') UNION ALL SELECT 'function:'||n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')', md5(jsonb_build_array(pg_get_functiondef(p.oid),pg_get_userbyid(p.proowner),p.proacl,p.proconfig)::text) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','private','credentialing') AND p.prokind IN ('f','p')) SELECT count(*) AS compared_objects, md5(string_agg(identity||':'||fingerprint,E'\n' ORDER BY identity)) AS partial_catalog_md5 FROM objects; COMMIT;

